      "id": "c02-l04-p02-002",
      "title": "ギリシア独自の国家形態「ポリス」の出現だ！",
      "body": [
        "もう一つの典型が「征服型ポリス」だ。こっちは、南下してきたギリシア人が先住民を征服・隷属させて成立したポリスだよ。あとはマケドニアみたいにポリスを形成せず、そのまま王政が残った国もある。ただ、どちらにしても国の規模はそれほど大きくない。一番大きなアテネでさえ、全盛期の人口は30万人程度といわれているからね。だからギリシア人たちは、自分たちを「ポリスの市民」って認識していて、強い連帯感を持っていたんだ。",
        "ポリス意識が強い一方で、ギリシア人という意識も結構強かったよ。各ポリスの間ではたびたび戦争していても、経済的・文化的な交流も深かったから、同じギリシア語を話す人たちをヘレネスって呼んだ。伝説上の英雄ヘレンの子孫って意味だよ。ちなみに、ギリシア語を話さない異民族は、「聞き苦しい言葉を話す人」という意味でバルバロイと区別された。"
      ],
