      "id": "c02-l04-p02-004",
      "title": "ポリスの市民という意識は強いけど、ギリシア人という意識もある！",
      "body": [
        "そして、ギリシア人は何かあると神託（神のお告げ）を聞いたんだけど、最も権威があるとされたのが、デルフォイ【デルフィ】の神託だ。デルフォイにあるアポロン神殿にはギリシア各地のポリスが神託を聞くために集まり、植民市建設の位置や宣戦・講和なんかを、この神託で決めたよ。アポロンはもともと竪琴を持つ音楽の神だったり、予言や医術を司る神だったのが、のちに太陽神になったんだ。",
        "あと、ゼウス神殿のあるオリンピアでは、4年ごとに祭典と競技会がおこなわれ、期間中はいっさいの戦いが中止された。これが古代オリンピックだよ。でも参加できたのは裕福な貴族の、しかも男性だけ。こんなふうに共通の信仰を持つギリシア人たちだけど、基本的に強い神は12神だから、同じ神を祭るポリスも結構ある。そこで、同一の神への信仰を持つポリスが結んだ宗教的同盟が隣保同盟だ。例えば、デルフォイの神託を中心とする同盟には、スパルタを除くほぼ全ギリシアのポリスが参加していたよ。"
      ],
      "plainBody": [
        "そして、ギリシア人は何かあると神託（神のお告げ）を聞いたんだけど、最も権威があるとされたのが、デルフォイ【デルフィ】の神託だ。デルフォイにあるアポロン神殿にはギリシア各地のポリスが神託を聞くために集まり、植民市建設の位置や宣戦・講和なんかを、この神託で決めたよ。アポロンはもともと竪琴を持つ音楽の神だったり、予言や医術を司る神だったのが、のちに太陽神になったんだ。",
        "あと、ゼウス神殿のあるオリンピアでは、4年ごとに祭典と競技会がおこなわれ、期間中はいっさいの戦いが中止された。これが古代オリンピックだよ。でも参加できたのは裕福な貴族の、しかも男性だけ。こんなふうに共通の信仰を持つギリシア人たちだけど、基本的に強い神は12神だから、同じ神を祭るポリスも結構ある。そこで、同一の神への信仰を持つポリスが結んだ宗教的同盟が隣保同盟だ。例えば、デルフォイの神託を中心とする同盟には、スパルタを除くほぼ全ギリシアのポリスが参加していたよ。"
      ],
