      "title": "地中海各地に進出したギリシア人は、各地に植民市を建設！",
      "body": [
        "同じころ、ポリスの発展とともにギリシア全体の商工業も発展するよ。背景にはリディア王国から伝わった鋳造貨幣（コイン）の使用がある。貨幣の使用はアナトリアのイオニア地方からギリシア世界全体に広がり、経済活動を刺激した。そして、交易の活発化にともなって、ポリスの海上活動もしだいに盛んとなり、前8世紀半ばには地中海各地に植民市が建設されていったんだ。",
        "ギリシア人の植民活動の背景には、こうした経済活動の活発化だけではなく、人口の増加による土地不足や、貴族の間の権力闘争なども考えられるね。内部対立で危機に陥ったポリスが、対立を対外進出でうやむやにしてしまおうってことだよ。"
      ],
