      "id": "c02-l04-p05-007",
      "title": "ペルシアに備えてデロス同盟を結成。でも……アテネが同盟を私物化",
      "body": [
        "第3回ペルシア戦争後も、ギリシア側は「またペルシアが攻めてきたらどうしよう……」って恐れていた。そこで、再度のペルシアの侵攻に備えた海上軍事同盟として、アテネを盟主にデロス同盟が結成された。この同盟はデロス島に海軍基地をつくってギリシアの東方海上を守るのが目的だ。加盟したポリスは、艦船・兵員、もしくは軍資金を出すことになったけど、ほとんどのポリスは軍資金を払ったよ。",
        "ところが、ペルシア軍はもう攻め込んでこなかったから、もはや海上同盟の意味はなくなった。そこでアテネは、同盟の金庫をアテネに移したんだけど、これは大問題。各ポリスは、ペルシアに対する防衛のためにお金を出したのに、勝手にアテネに持っていくのはおかしいでしょ？　これじゃあ、他のポリスがアテネに税金払ってるのと同じだ。しかも、前449年にカリアスの和約が結ばれて正式にペルシア戦争が終結しても、デロス同盟は解散されずにアテネがその資金を私物化したんだよ。加盟したポリスはアテネの貨幣を使用することを強制されたり、軍事拠点にはアテネの植民市がつくられたりして、アテネによるギリシア支配が強まった。こういう状態を「アテネ帝国」って呼ぶけど、アテネ皇帝がいたわけじゃないからね。",
        "さて、ペルシア戦争が終わると、いよいよアテネの民主政が完成するんだけど、それもつかの間……ギリシアは再び混乱の時代を迎えるよ。続きは次回！"
      ],
