      "id": "c02-l05-p02-003",
      "title": "スパルタが覇権を握ったけど、テーベに敗れる！",
      "body": [
        "しかしスパルタは、各ポリスにスパルタの役人や軍隊を派遣して強引に覇権を確立したから、反感も高まった😅。しかも、スパルタの強大化を嫌がって、アケメネス朝はアテネの復興を支援した。ほら、今度はNo.1になったスパルタを潰そうとしてる😅。作戦どおりでしょ！　そして、アケメネス朝の支援を受けたテーベの呼びかけでアテネ・コリントスなどが連合して、スパルタを攻撃した。これがコリントス戦争だ。このときスパルタは、アケメネス朝にアナトリアのギリシア人諸都市の支配権をすべて委ねることで、戦争を終結させたんだ（大王の和約）。ギリシア内部の混乱はアケメネス朝次第、ってことになっちゃったね。",
        "さらに天才的な軍事指導者エパメイノンダスが登場したテーベが、ファランクス（重装歩兵密集陣形）による斜線陣形と騎兵を使う新戦術を導入して、一気に強大化した。そして、前371年にレウクトラの戦いでスパルタを破ると、今度はテーベがギリシアの覇権を握ったんだ。"
      ],
