      "id": "c02-l05-p02-006",
      "title": "マケドニアにフィリッポス2世が登場！",
      "body": [
        "マケドニア軍の進出を受けて、アテネでは和平派のイソクラテスと主戦派のデモステネスが対立した。90歳近くなっていたイソクラテスは、もはやアテネには全ギリシアを統率する力はないと判断して、「マケドニアを中心にギリシアを統合してペルシア討伐をすべし🔨」って主張した。対するデモステネスは主戦論を説き、市民の反マケドニア感情を煽った。どっちが正しいとかじゃなくて、結局「絶対勝てる」みたいな勇ましい主張をしているデモステネスのほうが、じーさんのイソクラテスより人気が出ちゃった……😅。",
        "こうして市民は反マケドニアに傾き、アテネはデモステネスの提案によってマケドニアに宣戦、テーベと同盟してマケドニアと戦うことになった。これがカイロネイアの戦い［前338］だ。しかし、この戦いでは戦闘経験と戦術に勝るマケドニア軍がアテネ・テーベ連合軍に圧勝し、マケドニアがギリシアの覇権を握ったんだ。"
      ],
