      "id": "c02-l07-p01-003",
      "title": "オクタウィアヌスが始めた「元首政」ってなんだろう？",
      "body": [
        "そして、彼の地位は養子のティベリウス帝に受け継がれて帝位が世襲され、共和政には戻らなかった。こうして、ローマ皇帝の圧倒的な権力によって、以後約200年間は非常に安定した平和な時代が続いたよ。これが「<span class=\"source-bold\">パクス＝ロマーナ【ローマの平和】</span>」だ。あとでじっくり解説するからね。ちなみに、ティベリウスはイエスが処刑されたときの皇帝だよ。",
        "ただ、晩年のアウグストゥス（オクタウィアヌス）には、予期せぬ災いが降りかかってきた。ライン川を越えた現在の北ドイツあたりで、ローマ軍がゲルマン人に大敗して壊滅し（トイトブルクの森の戦い［後9］）、ローマはライン川以北の領土を放棄した。あんなに強かったのに……とはいっても、彼の親友で軍事的な天才だったアグリッパはすでに亡くなっている……😢。この結果、ローマとゲルマン人の国境は<span class=\"source-bold\">ライン川・ドナウ川</span>の線となったよ。"
      ],
