      "id": "c02-l07-p01-004",
      "title": "平和と繁栄のなかで……暴君ネロが登場！",
      "body": [
        "ゲルマン人に敗北したとはいえ、ローマ帝国はすでに周辺諸国を圧倒し、経済的にも繁栄していた。ただ、繁栄のなかで混乱する時代もあった。それがネロ帝の治世だ。「ネロ」といったら、暴君の代名詞！　どんな皇帝だったんだろう？",
        "弱冠17歳で皇帝に就任したネロは、ストア派哲学者の<span class=\"source-bold\">セネカ</span>の補佐を受けて最初はよい皇帝だった。ところが、よかったのは最初の5年だけ😨。セネカを自殺させたり、母親や奥さんまで殺したり、政治はほったらかしで、趣味の歌や演劇のめりこんだりと、だんだん本性を現して暴君になった。そして、64年のローマの大火の際に、放火犯として<span class=\"source-bold\">キリスト教徒を迫害</span>した。このとき、ペテロやパウロが処刑されたといわれている。そんなネロも、最後は失脚して自殺に追い込まれた。"
      ],
