      "id": "c02-l07-p01-006",
      "title": "ローマ帝国の全盛期、「パクス＝ロマーナ」って何？",
      "body": [
        "多くの場合、属州の都市って最初は軍団駐屯地だったんだけど、それがだんだんとローマ風の都市に発展していくよ。だって、ローマは憧れの都市だもん、別格だ！　人口も余裕で100万人を超えて、大規模な建築事業によって、日々発展を続けている。だから、各地の富裕になった人びとは、みんなでお金を出し合って、憧れの都ローマみたいな都市をつくろうとしたんだね。この時期に建設された都市には、<span class=\"source-bold\">ロンディニウム（現：ロンドン）・ウィンドボナ（現：ウィーン）・ルテティア（現：パリ）・ルグドゥヌム（現：リヨン）・メディオラヌム（現：ミラノ）</span>などがあるよ。こうして、帝国全土にギリシア・ローマ文化の融合した都市的な文化が広がったんだ。そして帝国政府の政策もあって、<span class=\"source-bold\">ラテン語</span>が全国に普及したよ。"
      ],
