      "id": "c02-l07-p01-007",
      "title": "ローマ帝国の全盛期、「パクス＝ロマーナ」って何？",
      "body": [
        "さらに、この時期にはインド洋の<span class=\"source-bold\">季節風貿易</span>やイランを経由したシルクロードの隊商交易によって、アジアから香辛料・絹・貴金属・宝石などが、地中海に運ばれてきたよ。イランとインドのところで話したのを覚えてるかな？　<span class=\"source-bold\">パルティアやサータヴァーハナ朝</span>が繁栄したのは、この時代のローマと後漢を結ぶ交易の発展が背景だよ。中国の歴史書『後漢書』「西域伝」に記された<span class=\"source-bold\">大秦王安敦（マルクス＝アウレリウス＝アントニヌス帝だ！）</span>の使者が日南郡に入貢するのも、この時代だ。",
        "こうして、帝国全土で経済活動が活発になり、整備された交通網によって、各地を結ぶ盛んな交易がおこなわれるようになった。ちょっと難しい言い方をすると、「帝国全土が一つの広域経済圏」になった。そして、属州各地に建設された都市がこの繁栄を支えたから、帝国内での属州の地位が向上していくんだ。"
      ],
