      "title": "イタリアの地位が低下……ついに全帝国に市民権が拡大！",
      "body": [
        "あと、カラカラ帝は市民の人気を集めるために、空前の規模の<span class=\"source-bold\">大浴場（カラカラ浴場）</span>を建設したよ。大浴場ってのは、今で言うと「温泉＋スポーツジム＋ネットカフェ＋図書館」みたいな総合娯楽センターだ。今でもローマに残っている遺跡から、大げさな人気取り政策だとわかるよ。でも、そんなんじゃローマ史上随一の暴君といわれる彼の悪評は消えない😨。残忍な性格だったカラカラは、親衛隊の兵士によって殺されたんだ。"
      ],
