        "さて、「3世紀の危機」はわかったかな？　ここはローマ帝国内で起こっていた社会の変化だから、なかなかイメージしにくいところだね。少し難しいかもしれないけど、元首政が崩壊して専制君主政へと変わっていく背景だから、しっかりと流れをつかもう。それじゃあ、専制君主政に進むよ！"
