      "id": "c02-l07-p03-003",
      "title": "ついに、政策転換。コンスタンティヌス帝がキリスト教公認！",
      "body": [
        "ディオクレティアヌス帝が皇帝を引退したあとの帝位をめぐる混乱を収めたのが<span class=\"source-bold\">コンスタンティヌス帝</span>（副帝から西の正帝になった）とリキニウス帝の連合だ。すでに帝国内では、迫害にもかかわらず東方を中心にキリスト教が拡大しているから、全部を敵に回したら、かえって混乱がデカくなる。しかも、帝位をめぐる対立勢力は、キリスト教徒の迫害を続けている。コンスタンティヌス帝は「キリスト教を認めてしまって、こいつらを味方にしたほうが得だ😆」と考え、東方のリキニウス帝との連名で、313年<span class=\"source-bold\">ミラノ勅令</span>を発布して<span class=\"source-bold\">キリスト教を公認</span>した。こうして、帝国統治の宗教的な基盤として、キリスト教が利用されるようになったんだ。注意してほしいのは、このときコンスタンティヌス帝はキリスト教徒じゃない！　公認したのは帝国統治を有利に進めるためだから、この時点では「キリスト教、伝統的な宗教、どちらを信仰してもOK」だよ。",
        "そして、コンスタンティヌス帝は公認後のキリスト教徒を保護したから、急速にキリスト教徒が増えた。さらに迫害中に没収した財産も教会に返還した。これも、キリスト教迫害を再開した東のリキニウス帝より自分のほうがいい皇帝だ！って見せるためだよ。一方、キリスト教の側も皇帝に接近し、教会史家の<span class=\"source-bold\">エウセビオス</span>は皇帝を神の代理人とする神権帝理念を打ち出しているよ。"
      ],
