      "id": "c02-l07-p03-005",
      "title": "都が「コンスタンティヌスの街」へ！",
      "body": [
        "帝国統治が確立されるにつれて皇帝の専制化がさらに進み、官僚機構が強化され、国民の職業も固定化された。<span class=\"source-bold\">コロヌスの移動禁止（コロヌス土地緊縛）</span>が定められて、コロヌスは住所も身分も変えられなくなった。これが中世農奴制の起源だよ。",
        "それから、コンスタンティヌスは非常に純度の高い<span class=\"source-bold\">ソリドゥス金貨</span>を発行して、安定した通貨制度をつくった。この金貨が以後の基軸通貨となって国際的に流通し、ビザンツ帝国でもノミスマの名で鋳造され続けたんだ。ドルの記号「＄」が「0」じゃなくて「S」を使っているのは、ソリドゥス金貨みたいに信用の高い通貨になるように、っていう願いからだよ。"
      ],
