      "id": "c02-l07-p03-006",
      "title": "「背教者」ユリアヌス。背教って……本当に裏切りなの？",
      "body": [
        "キリスト教が公認されたあとも、すべての皇帝がキリスト教徒だったわけでもない。361年に登場した<span class=\"source-bold\">ユリアヌス帝</span>は、イラン経由で伝わった古代アーリヤ人の太陽神<span class=\"source-bold\">ミトラ</span>を信仰した。超まじめだったユリアヌスは、「正統だ、異端だ」とキリスト教徒同士が敵対し合い、権力と結びついた教会に嫌気が差していた😨。堕落した信仰を嫌ったユリアヌスが、一番純粋な信仰を持っていたんだね。そして、弾圧したわけでもないのに、教会は彼を裏切り者の「<span class=\"source-bold\">背教者</span>」と呼んだ。そんな彼も、即位からわずか2年でササン朝への遠征中に戦死してしまったんだ。"
      ],
