      "id": "c02-l07-p04-005",
      "title": "初期のキリスト教は、迫害の歴史！",
      "body": [
        "ローマの信仰は多神教だった。例えば、ギリシアのオリンポス12神やエジプトのオシリス神話の神イシス信仰、古代アーリア人のミトラ教などだ。そこに現れたキリスト教は単なる新興宗教だったから、人びとはユダヤ教との区別もあまりつかず、キリスト教のほうが危ない宗教と思われていた。しかも、一神教は多神教信仰のローマでは異質な存在だから、ネロ帝の迫害の標的となったんだ😨。",
        "その後、ユダヤ人が反乱を起こしてイェルサレムから追放され、各地に離散すると（ディアスポラ）、反乱に加わらなかったキリスト教徒がユダヤ人とは区別されるようになった。でも、キリスト教徒は危険！という認識は大して変わらなかったから、ディオクレティアヌス帝の大迫害まで、キリスト教徒は迫害されるんだ。"
      ],
