      "id": "c02-l07-p04-008",
      "title": "キリスト教の公認から国教化へ。ポイントは異端の排除だ！",
      "body": [
        "その後、テオドシウス帝がキリスト教を国教化すると、皇帝がキリスト教の支配者であり保護者となるから、アタナシウス派以外はすべて異端として排除するよ。まず、431年に東ローマ皇帝テオドシウス2世によってエフェソス公会議が開かれ、イエスの神の部分（神性）と人の部分（人性）を完全に分離するネストリウス派が異端とされた。ネストリウス派は、その後ササン朝を中心に東方へと拡大し、唐代の中国にまで伝わって景教と呼ばれた。さらに451年に東ローマ皇帝マルキアヌスが開いたカルケドン公会議で「イエスは完全に神」と考える単性論が異端とされた。単性論はシリアや北アフリカに拡大し現在まで残っている。エジプトやエチオピアで独自の活動を続けているコプト教会は単性論を信奉しているよ。",
        "じゃあ、なんで異端となったあとも彼らが活動できるんだろう？　それは、異端とは「ローマ帝国（もちろん東西分裂したあともね）のなかでは異端」ということだから、ローマ帝国の外に出てしまえば異端もへったくれもない😅。だから、帝国外の各地域に拡大したんだよ。"
      ],
